---@type string[]
local arg = {}
---@diagnostic disable
-- Generated by nvim-bundle; do not edit.
-- returns: args
local __mods = {}
---@return { loaded: table<string, any>, LOADING: table }
local function __cache()
  local private = { loaded = {}, LOADING = {} }
  local nvim, info = rawget(_G, 'vim'), debug.getinfo(1, 'Sl')
